import{_ as n,l as i,o as a,c as l,v as r,p,x as o,d as s,i as R,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"DeepSeek-R1 论文","description":"","frontmatter":{"title":"DeepSeek-R1 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deepseek-r1-paper.md","filePath":"llm/deepseek-r1-paper.md","lastUpdated":1789023840000}'),E={name:"llm/deepseek-r1-paper.md"};function d(m,e,A,c,B,S){const t=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="deepseek-r1-论文" tabindex="-1">DeepSeek-R1 论文 <a class="header-anchor" href="#deepseek-r1-论文" aria-label="Permalink to &quot;DeepSeek-R1 论文&quot;">​</a></h1><div class="epigraph"><p>R1-Zero 从基座直接大规模强化学习，不先做监督微调；R1 再用冷启动与多阶段训练把可读性补回来，并把长链蒸馏到稠密小模型。</p><footer>—— DeepSeek-AI，DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning，2025</footer></div><p>DeepSeek-R1 报告给出两个检查点与一条蒸馏线。DeepSeek-R1-Zero 从 DeepSeek-V3-Base 出发，跳过 SFT，用 <a href="/llm/grpo-paper">GRPO</a> 与规则奖励做大规模 RL，长链、自检与试错在训练曲线上自己长出来。DeepSeek-R1 在 RL 前加入数千条冷启动长链，并经过「推理 RL → 拒绝采样再 SFT → 全场景 RL」；报告称推理任务对标当时的 OpenAI-o1-1217。开源还包括 1.5B–70B 的 Qwen / Llama 稠密蒸馏。推理时行为与服务含义见 <a href="/llm/deepseek-r1">DeepSeek-R1 与推理时行为</a>；本篇钉论文里的阶段、奖励、超参与表上的数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常规助手先 SFT 模仿人类短解，再 RLHF。人类示范很少出现「写数千 token 草稿纸再改答案」，过程人标又贵。作者想验证：若奖励<strong>只看最终对错与格式</strong>，不管中间写什么，策略会不会自己发明可用的中间过程？这要求可验证任务（数学、代码、能判分的逻辑），以及一种不必再训与 671B MoE 同规模 critic 的 RL。GRPO 在 DeepSeekMath 里已经用过；R1 把它拉到 V3 基座与数万 token 的生成长度。</p><p>Zero 立刻暴露产品缺陷：中英混杂、难读、思维对用户不友好。第二个问题是：如何在不把长链能力打回去的前提下加入人类可读先验，并覆盖写作、事实问答、自我认知等非可验证场景。第三个问题是社区复现成本：完整 RL 太贵，长链文本能否单靠 SFT 迁到小稠密模型。</p><h3 id="作者明确没有采用的路线" tabindex="-1">作者明确没有采用的路线 <a class="header-anchor" href="#作者明确没有采用的路线" aria-label="Permalink to &quot;作者明确没有采用的路线&quot;">​</a></h3><p>报告写明 R1-Zero <strong>不用</strong>过程奖励模型，也<strong>不用</strong> MCTS 当主训练环。中间过程不被逐步打分，信用完全来自终点规则。这与 <a href="/llm/verify-step">Lightman</a> 的验证器路线、<a href="/llm/vineppo">VinePPO</a> 的训练期逐步 MC 都不同。引用时不要把 PRM 或树搜索写进 R1-Zero 的方法节。</p><p><span class="marginnote">AIME 2024 上 Zero 的 pass@1，初版摘要写 15.6%→71.0%，后续修订稿图与表出现 77.9% 等更新。cons@16 为 86.7%。引用必须标明版本与 pass@1 / 投票协议。R1 主表 AIME pass@1 约 79.8%，与报告中的 o1-1217 对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>奖励。</strong> 可验证题：答案对错（数学解析、代码测试）。格式：思维落在指定标签内，便于切分。没有逐步过程分。R1 的推理 RL 阶段另加语言一致性（目标语言词占比），以减轻混写，作者承认这会微损推理分。第二段全场景 RL 把有用性、无害性接回奖励模型（对摘要或可见回答打分，并考虑思维），与规则奖励并存。</p><p><strong>GRPO 设定（Zero）。</strong> 学习率 \\(3\\times 10^{-6}\\)，KL 系数 \\(0.001\\)，rollout 温度 1。每题 16 个输出；最大长度在约 8.2k 步前为 32,768，之后 65,536，曲线在该点有一跳。共约 10,400 步、1.6 epoch。每步 32 道题，batch 512。每 400 步把参考策略换成最新策略。每次 rollout 8192 条，切 16 个 mini-batch，内层只训 1 个 epoch。clip \\(\\varepsilon\\) 在 R1 阶段叙述中出现过较大值（文中写到 10）以配合长链。</p><p><strong>R1 四段。</strong> （1）数千条冷启动：人把 Zero 风格改成第一人称、可读、语言一致，再让模型扩写并经人审，SFT V3-Base。（2）与 Zero 类似的推理 RL，加语言一致性。（3）在 RL 检查点上拒绝采样，混入 V3 的写作 / 事实 / 自我认知等监督，约 80 万样本，再 SFT。（4）全场景 RL：推理规则奖励 + 有用无害。蒸馏：用 R1 轨迹对 Qwen2.5 与 Llama-3.1/3.3 等做 <strong>2–3 epoch 纯 SFT、不再 RL</strong>，上下文 32,768，报告把「小模型再 RL」留给社区。</p>',13)),(a(),p(h,null,{default:o(()=>[R(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22DeepSeek-V3-Base%22%5D%20--%3E%20Z%5B%22R1-Zero%EF%BC%9A%E6%97%A0%20SFT%EF%BC%8CGRPO%20%2B%20%E8%A7%84%E5%88%99%E5%A5%96%E5%8A%B1%22%5D%0A%20%20Z%20--%3E%20E%5B%22%E6%B6%8C%E7%8E%B0%E9%95%BF%E9%93%BE%20%2F%20%E8%87%AA%E6%A3%80%EF%BC%9B%E6%B7%B7%E8%AF%AD%E8%A8%80%E3%80%81%E9%9A%BE%E8%AF%BB%22%5D%0A%20%20B%20--%3E%20CS%5B%22%E5%86%B7%E5%90%AF%E5%8A%A8%E9%95%BF%E9%93%BE%20SFT%22%5D%0A%20%20CS%20--%3E%20RL1%5B%22%E6%8E%A8%E7%90%86%20RL%20%2B%20%E8%AF%AD%E8%A8%80%E4%B8%80%E8%87%B4%E6%80%A7%22%5D%0A%20%20RL1%20--%3E%20RS%5B%22%E6%8B%92%E7%BB%9D%E9%87%87%E6%A0%B7%20%2B%20%E5%A4%9A%E5%9F%9F%20SFT%20~800k%22%5D%0A%20%20RS%20--%3E%20RL2%5B%22%E5%85%A8%E5%9C%BA%E6%99%AF%20RL%22%5D%0A%20%20RL2%20--%3E%20R1%5B%22DeepSeek-R1%22%5D%0A%20%20R1%20--%3E%20D%5B%22%E8%92%B8%E9%A6%8F%E5%88%B0%20Qwen%20%2F%20Llama%20%E7%A8%A0%E5%AF%86%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="与-ppo-的附录对照" tabindex="-1">与 PPO 的附录对照 <a class="header-anchor" href="#与-ppo-的附录对照" aria-label="Permalink to &quot;与 PPO 的附录对照&quot;">​</a></h3><p>附录在 DeepSeek-Coder-V2-Lite 上比 PPO 与 GRPO：PPO 对 GAE 的 \\(\\lambda\\) 敏感，\\(\\lambda=0.95\\) 明显弱于 GRPO，\\(\\lambda=1.0\\) 才接近。PPO 还要价值模型显存。R1 选 GRPO 是资源与稳定性，不是定理上淘汰 PPO。KL 放在损失里、并周期性更新 \\(\\pi_{\\mathrm{ref}}\\)，是为了避免 InstructGPT 式逐步 KL 惩罚隐式打压长度——长链正是他们要的。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="长度是被奖励定价的-不是架构加出来的" tabindex="-1">长度是被奖励定价的，不是架构加出来的 <a class="header-anchor" href="#长度是被奖励定价的-不是架构加出来的" aria-label="Permalink to &quot;长度是被奖励定价的，不是架构加出来的&quot;">​</a></h3><p>终点正确率随思维变长而升时，组内相对优势偏向更长的探索轨迹，平均回复长度在训练曲线上上升。反思、换解法，是 token 空间里的探索被强化，不是额外模块。格式奖励把思维与答案切开，既方便解析，也方便产品折叠。混语言：奖励不管用哪国语言思考，若中英切换偶然提高正确率就会留下；冷启动把分布拉回服务语言。</p><p><span class="marginnote">组大小 \\(G=16\\)、温度 1、最大长度数万，是这条涌现曲线的实验条件。把 \\(G=1\\) 或把 max length 截到聊天默认，复现的不是这篇论文。</span></p><h3 id="蒸馏证明文本程序可迁移" tabindex="-1">蒸馏证明文本程序可迁移 <a class="header-anchor" href="#蒸馏证明文本程序可迁移" aria-label="Permalink to &quot;蒸馏证明文本程序可迁移&quot;">​</a></h3><p>小模型没做 RL，只模仿 R1 的长链。报告用这一点说明：昂贵探索的结果可以写成数据。这不等于计算最优压缩，也不等于小模型拥有同一搜索深度——截断与教师失败模式会一起过来。32B 蒸馏在部分数学集上接近当时 o1-mini 一档，具体格以原文表为准，且与 s1-32B 的 1K SFT 不是同一数据量级（R1 蒸馏约 800k）。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>规则奖励覆盖不了开放写作；第二段 RM RL 才补助手属性，其 RM 细节不如数学规则透明。过程无监督意味着假推理仍存在：看起来在验证，中间仍错，只要终点过检查器。过度思考：简单题仍可能写很长。o1-1217 对照受 API 与官方数限制，报告已说明部分封闭分数来自官方披露。许可证与权重以当时仓库为准。</p><p>不要把 V3 的 MLA/MoE 写成 R1 的贡献；骨架是 V3，变的是后训练与长度分布。不要把 GRPO 写成 2025 年才出现——它来自 2024 的 DeepSeekMath。</p><p><span class="marginnote">公开权重使复现与蒸馏成为可能；完整 Zero 的 RL 算力与数据配比仍有报告未列全的部分（题库构成、代码环境细节）。写「完全可复现」要谨慎，写「算法与阶段公开」是准确的。</span></p><h3 id="何时不必走-r1-全流程" tabindex="-1">何时不必走 R1 全流程 <a class="header-anchor" href="#何时不必走-r1-全流程" aria-label="Permalink to &quot;何时不必走 R1 全流程&quot;">​</a></h3><p>只有 1K 条教师长链、没有 RL 集群，看 <a href="/llm/s1-budget-forcing">s1</a>。已有逐步人标、想做验证器，看 Lightman。对话短、延迟紧，不要把 R1 当默认聊天策略。需要无偏逐步信用分配且买得起训练期 MC，VinePPO 回答的是另一问。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>R1-Zero：V3-Base 上纯 GRPO + 规则奖励，无 SFT、无 PRM、无 MCTS；长链在 RL 中涌现。</li><li>R1：冷启动 SFT → 推理 RL → 约 80 万拒绝采样 SFT → 全场景 RL。</li><li>超参公开到组大小、KL、长度跳变步、周期性更新参考策略。</li><li>蒸馏小模型默认仅 SFT；报告把小模型再 RL 留给社区。</li><li>AIME 等数字须标明 pass@1 / 投票与论文版本；o1 对照是当时声明。</li><li>出处：DeepSeek-AI，<em>DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning</em>，arXiv:2501.12948，2025。</li></ul>',16))])}const L=n(E,[["render",d]]);export{k as __pageData,L as default};
